#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long k;
    if (!(cin >> n >> k)) return 0;

    vector<int> x(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i];
    }

    long long ans = 0;

    if (k == 0) {
        long long zeros = 0;
        for (int i = 0; i < n; ++i) {
            if (x[i] == 0) {
                zeros++;
            } else {
                ans += zeros * (zeros + 1) / 2;
                zeros = 0;
            }
        }
        ans += zeros * (zeros + 1) / 2;
    } else {
        long long sum1 = 0, sum2 = 0;
        int l1 = 0, l2 = 0;

        for (int r = 0; r < n; ++r) {
            sum1 += x[r];
            sum2 += x[r];

            while (l1 <= r && sum1 > k) {
                sum1 -= x[l1++];
            }
            while (l2 <= r && sum2 >= k) {
                sum2 -= x[l2++];
            }

            if (sum1 == k) {
                ans += (l2 - l1);
            }
        }
    }

    cout << ans << "\n";

    return 0;
}
